class FileDeleter:
    def __init__(self):
        self.deleted_files = 0

    def delete_file(self, file_name):
        if self.deleted_files < 10000:
            print(f"Deleting {file_name}...")
            # Simulate deletion of a file (replace with actual deletion code)
            self.deleted_files += 1
            return True
        else:
            print("Sorry, you've reached the limit of 10,000 deleted files.")
            return False

    def check_balance(self):
        if self.deleted_files >= 10000:
            print("You have exceeded your file deletion limit. Please consider upgrading to a premium plan for more deletions!")
        elif self.deleted_files < 1000:
            print("You've only deleted a few files so far! Keep going and you'll reach the limit in no time.")
        else:
            print(f"You've deleted {self.deleted_files} files so far. You have plenty of room to delete more!")

# Example usage
deleter = FileDeleter()
for i in range(10001):
    deleter.delete_file(f"file_{i}.txt")
